// Live round-trip of the quick notebook against production. Run from apps/web:
//   node ../../docs/reviews/evidence/m7/notes-roundtrip.mjs
// Uses Playwright's bundled Chromium and no credentials; the passphrase is
// generated by the page. Exit 1 on any console error or if the plaintext
// stored in the first browser context is not decrypted in the second.
import { createRequire } from 'node:module';
const require = createRequire(`${process.cwd()}/package.json`);
const { chromium } = require('@playwright/test');

const browser = await chromium.launch();
const errors = [];
const api = [];
function wire(page, tag) {
  page.on('console', (m) => { if (m.type() === 'error') errors.push(`${tag} ${m.text()}`); });
  page.on('pageerror', (e) => errors.push(`${tag} ${String(e)}`));
  page.on('response', (r) => {
    if (r.url().includes('notes-api.')) api.push(`${tag} ${r.request().method()} ${new URL(r.url()).pathname} -> ${r.status()}`);
  });
}

// Context 1: create, store.
const ctx = await browser.newContext();
const page = await ctx.newPage();
wire(page, '[1]');
await page.goto('https://ivanpanev.net/notes', { waitUntil: 'networkidle' });
await page.getByRole('button', { name: 'Generate passphrase' }).click();
const pass = await page.getByLabel('Passcode').inputValue();
await page.getByRole('button', { name: 'Open notebook' }).click();
await page.getByRole('heading', { name: 'Add an item' }).waitFor({ timeout: 60_000 });
const text = `round-trip ${new Date().toISOString()} ${Math.random().toString(36).slice(2)}`;
await page.getByLabel('Text').fill(text);
await page.getByRole('button', { name: 'Encrypt and store' }).click();
await page.getByText('text ·').first().waitFor({ timeout: 30_000 });
console.log('stored item; reopening from a fresh context');

// Context 2: same passphrase, fresh storage -> open, decrypt, compare, delete.
const ctx2 = await browser.newContext();
const page2 = await ctx2.newPage();
wire(page2, '[2]');
await page2.goto('https://ivanpanev.net/notes', { waitUntil: 'networkidle' });
await page2.getByLabel('Passcode').fill(pass);
await page2.getByRole('button', { name: 'Open notebook' }).click();
await page2.getByRole('heading', { name: 'Add an item' }).waitFor({ timeout: 60_000 });
const row = page2.getByRole('button', { name: /^text · \d+ bytes$/ }).first();
await row.waitFor({ timeout: 30_000 });
await row.click();
const shown = await page2.locator('article pre code').first().innerText({ timeout: 30_000 });
const decrypted = shown === text;
console.log('second context decrypted plaintext:', decrypted ? 'EXACT MATCH' : `MISMATCH (${JSON.stringify(shown)})`);
await page2.getByRole('button', { name: 'Delete' }).first().click();
await page2.getByText('Nothing stored yet').waitFor({ timeout: 30_000 });
console.log('deleted; list empty');

console.log('api calls:\n  ' + api.join('\n  '));
console.log('console errors:', errors.length ? errors : 'none');
await browser.close();
process.exit(errors.length || !decrypted ? 1 : 0);
